class Solution:
    def findLongestChain(self, pairs: list[list[int]]) -> int:
        arr = sorted(pairs)
        n = len(arr)
        def dfs(i: int, prev: int) -> int:
            if i == n:
                return 0
            ans = dfs(i + 1, prev)
            if prev == -1 or arr[prev][1] < arr[i][0]:
                ans = max(ans, 1 + dfs(i + 1, i))
            return ans
        return dfs(0, -1)

solutions.better:
class Solution:
    def findLongestChain(self, pairs: list[list[int]]) -> int:
        arr = sorted(pairs)
        n = len(arr)
        dp = [1] * n
        for i in range(n):
            for j in range(i):
                if arr[j][1] < arr[i][0]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp, default=0)

