class Solution:
    def findLongestChain(self, pairs: list[list[int]]) -> int:
        cur = -10**20
        ans = 0
        for left, right in sorted(pairs, key=lambda p: p[1]):
            if left > cur:
                ans += 1
                cur = right
        return ans

